print("meas desk keys:", list(r_meas_desk.output.keys()))
for k in r_meas_desk.output:
    if k != "points_world":
        print("desk", k, r_meas_desk.output[k])
for k in r_meas_dust.output:
    if k != "points_world":
        print("dust", k, r_meas_dust.output[k])

r_meas_desk_mm = primitives.call(name="measure_robotwin2_actor_visual", actor_label="deskbin", camera_name="head_camera", depth_scale=1000.0, max_points=500)
r_meas_dust_mm = primitives.call(name="measure_robotwin2_actor_visual", actor_label="dustbin", camera_name="head_camera", depth_scale=1000.0, max_points=500)
for k in r_meas_desk_mm.output:
    if k != "points_world":
        print("desk_mm", k, r_meas_desk_mm.output[k])
for k in r_meas_dust_mm.output:
    if k != "points_world":
        print("dust_mm", k, r_meas_dust_mm.output[k])

for k in r_meas_desk.output:
    val = r_meas_desk.output[k]
    if isinstance(val, list) and len(val) > 10:
        print("desk", k, "len=", len(val))
    else:
        print("desk", k, val)

r_meas_desk_s = primitives.call(name="measure_robotwin2_actor_visual", actor_label="deskbin", camera_name="head_camera", depth_scale=0.001, max_points=500)
r_meas_dust_s = primitives.call(name="measure_robotwin2_actor_visual", actor_label="dustbin", camera_name="head_camera", depth_scale=0.001, max_points=500)
for k in r_meas_desk_s.output:
    val = r_meas_desk_s.output[k]
    if isinstance(val, list) and len(val) > 10:
        print("desk_s", k, "len=", len(val))
    else:
        print("desk_s", k, val)
for k in r_meas_dust_s.output:
    val = r_meas_dust_s.output[k]
    if isinstance(val, list) and len(val) > 10:
        print("dust_s", k, "len=", len(val))
    else:
        print("dust_s", k, val)

r_scene = primitives.call(name="observe_robotwin2_scene", query="all actors and balls")
print("scene ok:", r_scene.ok)
if r_scene.ok:
    print("actor_names:", r_scene.output.get("actor_names"))

# Also let's inspect segmentation IDs in head_camera from r_vis
if r_vis.ok:
    for k, v in r_vis.output.items():
        if k != "cameras":
            print("r_vis", k, v)
    cams = r_vis.output.get("cameras", {})
    if "head_camera" in cams:
        print("head_cam keys:", list(cams["head_camera"].keys()))
        for ck, cv in cams["head_camera"].items():
            if not isinstance(cv, list) or len(cv) < 10:
                print("head_cam", ck, cv)
